"""50 MP, one-strip BigTIFF generated by independent system libtiff."""
import ctypes as C,ctypes.util,hashlib,json
from pathlib import Path
import numpy as np
from PIL import Image,features
source=Path('tests/fixtures/matting/native-50mp.png');data=np.asarray(Image.open(source).convert('RGBA'));height,width=data.shape[:2]
lib=C.CDLL(ctypes.util.find_library('tiff'));lib.TIFFOpen.argtypes=[C.c_char_p,C.c_char_p];lib.TIFFOpen.restype=C.c_void_p;lib.TIFFSetField.argtypes=[C.c_void_p,C.c_uint32];lib.TIFFSetField.restype=C.c_int;lib.TIFFWriteEncodedStrip.argtypes=[C.c_void_p,C.c_uint32,C.c_void_p,C.c_ssize_t];lib.TIFFWriteEncodedStrip.restype=C.c_ssize_t;lib.TIFFClose.argtypes=[C.c_void_p]
path=Path('tests/fixtures/tiff/native-50mp.tif');handle=lib.TIFFOpen(str(path).encode(),b'w8l');assert handle
try:
 for tag,value in [(256,width),(257,height),(258,8),(259,8),(262,2),(274,1),(277,4),(278,height),(284,1)]:assert lib.TIFFSetField(handle,tag,C.c_uint32(value))
 extra=C.c_uint16(2);assert lib.TIFFSetField(handle,338,C.c_uint32(1),C.byref(extra));assert lib.TIFFWriteEncodedStrip(handle,0,data.ctypes.data,data.nbytes)>=0
finally:lib.TIFFClose(handle)
path.with_suffix('.json').write_text(json.dumps({'generator':'system libtiff','version':features.version_codec('libtiff'),'source':str(source),'sourceSha256':hashlib.sha256(source.read_bytes()).hexdigest(),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'width':width,'height':height,'strips':1,'decodedStripBytes':data.nbytes},indent=2)+'\n');print(path,path.stat().st_size,'bytes; decoded strip',data.nbytes)
